use std::os::unix::ffi::OsStrExt;
fn c_atoi(bytes: &[u8]) -> i32 {
    let mut i = 0usize;
    while i < bytes.len() && matches!(bytes[i], b' '|b'\t'|b'\n'|0x0b|0x0c|b'\r') { i += 1; }
    let mut neg = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') { neg = bytes[i] == b'-'; i += 1; }
    let mut acc: i64 = 0;
    let mut overflow = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let d = (bytes[i] - b'0') as i64;
        if !overflow {
            match acc.checked_mul(10).and_then(|v| v.checked_add(d)) {
                Some(v) => acc = v,
                None => overflow = true,
            }
        }
        i += 1;
    }
    let val: i64 = if overflow { if neg { i64::MIN } else { i64::MAX } }
                   else if neg { -acc } else { acc };
    val as i32
}
